static unsigned checks=0;
static void check(bool ok,const char* error){++checks;if(!ok)throw std::runtime_error(error);}
template<class F>static bool rejects(F action){try{action();return false;}catch(const std::exception&){return true;}}
static std::string bytes(const live::fs::path& path){std::ifstream f(path,std::ios::binary);return {std::istreambuf_iterator<char>(f),std::istreambuf_iterator<char>()};}
static void file(const live::fs::path& path,const std::string& data){std::ofstream f(path,std::ios::binary|std::ios::trunc);f<<data;if(!f)throw std::runtime_error("Fixture write failed.");}
static std::vector<std::vector<std::string>> csv(const std::string& data){
    std::vector<std::vector<std::string>> rows;std::vector<std::string> row;std::string cell;bool quoted=false;
    size_t at=data.rfind("\xEF\xBB\xBF",0)==0?3:0;
    for(;at<data.size();++at){const auto c=data[at];if(c=='\"'){if(quoted&&at+1<data.size()&&data[at+1]=='\"'){cell+='\"';++at;}else quoted=!quoted;}
        else if(!quoted&&c==','){row.push_back(cell);cell.clear();}else if(!quoted&&c=='\n'){row.push_back(cell);cell.clear();rows.push_back(row);row.clear();}else if(c!='\r'||quoted)cell+=c;}
    if(quoted)throw std::runtime_error("Unclosed CSV quote.");return rows;
}
